// src/providers.ts
var TIMEOUT_MS = 5 * 60 * 1000;
var CLIENTS = {
  chatgpt: (apiKey) => createOpenAI({ apiKey }),
  gemini: (apiKey) => createGoogleGenerativeAI({ apiKey })
};
function configuredProviders(config) {
  return ["chatgpt", "gemini"].filter((p) => config.apiKeys[p]);
}
async function ask(config, provider, complexity, messages, abortSignal) {
  const model = config.models[provider][complexity];
  const apiKey = config.apiKeys[provider];
  if (!apiKey) {
    return { provider, model, response: "", error: "API Key nicht konfiguriert" };
  }
  try {
    const result = await generateText({
      model: CLIENTS[provider](apiKey)(model),
      messages,
      maxOutputTokens: 16384,
      timeout: TIMEOUT_MS,
      abortSignal
    });
    const { inputTokens, outputTokens } = result.usage;
    return { provider, model, response: result.text, usage: { inputTokens, outputTokens } };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return { provider, model, response: "", error: message };
  }
}

// src/sessions.ts
import { randomUUID } from "node:crypto";
import {
  mkdirSync,
  readFileSync,
  readdirSync,
  renameSync,
  rmSync,
  statSync,
  writeFileSync
} from "node:fs";
import { resolve as resolve3 } from "node:path";
var SESSIONS_DIR = resolve3(CONFIG_DIR, "sessions");
var TTL_MS = 2 * 60 * 60 * 1000;
var UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
var fileFor = (id) => resolve3(SESSIONS_DIR, `${id}.json`);
function cleanup() {
  let names;
  try {
    names = readdirSync(SESSIONS_DIR);
  } catch {
    return;
  }
  const now = Date.now();
  for (const name of names) {
    const file = resolve3(SESSIONS_DIR, name);
    try {
      if (now - statSync(file).mtimeMs > TTL_MS)
        rmSync(file);
    } catch {}
  }
}
function createSession(complexity, systemContext) {
  cleanup();
  return {
    id: randomUUID(),
    createdAt: new Date().toISOString(),
    systemContext,
    complexity,
    rounds: []
  };
}
function getSession(id) {
  if (!UUID.test(id))
    return;
  cleanup();
  try {
    return JSON.parse(readFileSync(fileFor(id), "utf-8"));
  } catch {
    return;
  }
}
function addRound(session, userMessage, results) {
  const round = {
    roundNumber: session.rounds.length + 1,
    userMessage,
    results,
    timestamp: new Date().toISOString()
  };
  session.rounds.push(round);
  try {
    mkdirSync(SESSIONS_DIR, { recursive: true, mode: 448 });
    const file = fileFor(session.id);
    writeFileSync(`${file}.tmp`, JSON.stringify(session, null, 2), {
      mode: 384
    });
    renameSync(`${file}.tmp`, file);
  } catch (err) {
    console.error("Failed to persist session:", err);
  }
  return round;
}
function buildMessages(session, newMessage, provider) {
  const messages = session.systemContext ? [{ role: "system", content: session.systemContext }] : [];
  let quoted = "";
  for (const round of session.rounds) {
    messages.push({ role: "user", content: quoted + round.userMessage });
    quoted = "";
    for (const r of round.results) {
      if (!r.response)
        continue;
      if (r.provider === provider) {
        messages.push({ role: "assistant", content: r.response });
      } else {
        quoted += `[Antwort von ${r.provider} (${r.model}) in Runde ${round.roundNumber}]:
${r.response}

`;
      }
    }
  }
  messages.push({ role: "user", content: quoted + newMessage });
  return messages;
}

